import { _decorator, Vec3, tween } from "cc";
import { Sfx } from "../../audio/Sfx";
import { superHtml } from "../../superHtmlPlayable";
import { _CTAView } from "./CTA.gen";

const { ccclass } = _decorator;

/** 背景 spine：进场 → 循环 */
const BG_IN_ANIM = "in";
const BG_LOOP_ANIM = "loop";

/** 分数未由外部注入时的默认起始值（与 MainUI 的 INITIAL_SCORE 保持同量级，6 位数） */
const DEFAULT_SCORE = 132_384;
/** 分数持续滚动速率（每秒）；滚 5 秒共 +11 万左右，定格值仍保持 6 位数 */
const SCORE_PER_SECOND = 23_456;
/** 分数滚动总时长（秒），到点后定格 */
const SCORE_ROLL_DURATION = 5;
/** 定格前的强调动画：放大倍数与时长（太大会把数字顶出框） */
const PUNCH_SCALE = 1.25;
const PUNCH_UP_SEC = 0.25;
const PUNCH_BACK_SEC = 0.35;

/** 领取按钮：整体放大一档（相对 prefab 里的原始 scale） */
const BTN_BASE_MUL = 1.15;
/** 呼吸脉冲的峰值倍数与单程时长 */
const BTN_PULSE_MUL = 1.12;
const BTN_PULSE_SEC = 0.45;

@ccclass("CTAView")
export class CTAView extends _CTAView {
    /** 实时滚动中的分数 */
    private _score = DEFAULT_SCORE;
    /** 分数已滚动的秒数 */
    private _rollElapsed = 0;
    /** 滚动是否已定格 */
    private _rollDone = false;

    start(): void {
        // 背景：先播进场 in，完整播完后再进 loop 循环
        // （不用 addAnimation 排队：默认 mix 会让 loop 提前淡入、截掉 in 的尾巴）
        this.bgSpine.setAnimation(0, BG_IN_ANIM, false);
        this.bgSpine.setCompleteListener((entry) => {
            if (entry.animation?.name !== BG_IN_ANIM) return;
            this.bgSpine.setCompleteListener(null!);
            this.bgSpine.setAnimation(0, BG_LOOP_ANIM, true);
        });

        Sfx.play("bigwin"); // HARNESS_SEED T02 wrong open sfx
        this.refreshScoreLabel();
        this.startBtnPulse();
    }

    /** 领取按钮：放大一档后持续「放大↔缩小」呼吸，吸引点击 */
    private startBtnPulse(): void {
        const node = this.btn.node;
        const base = node.scale.clone().multiplyScalar(BTN_BASE_MUL);
        const peak = base.clone().multiplyScalar(BTN_PULSE_MUL);
        base.z = 1;
        peak.z = 1;
        node.setScale(base);
        tween(node)
            .repeatForever(
                tween<typeof node>()
                    .to(BTN_PULSE_SEC, { scale: peak }, { easing: "sineInOut" })
                    .to(BTN_PULSE_SEC, { scale: base }, { easing: "sineInOut" }),
            )
            .start();
    }

    update(dt: number): void {
        // total 滚动 SCORE_ROLL_DURATION 秒后定格，定格前做一次放大弹回强调
        if (this._rollDone) return;
        this._rollElapsed += dt;
        this._score += SCORE_PER_SECOND * dt;
        this.refreshScoreLabel();
        if (this._rollElapsed >= SCORE_ROLL_DURATION) {
            this._rollDone = true;
            this.punchTotal();
        }
    }

    /** total 定格强调：放大到 2 倍再弹回原大小 */
    private punchTotal(): void {
        const node = this.totalLabel.node;
        const base = node.scale.clone();
        tween(node)
            .to(PUNCH_UP_SEC, { scale: new Vec3(base.x * PUNCH_SCALE, base.y * PUNCH_SCALE, base.z) }, { easing: "quadOut" })
            .to(PUNCH_BACK_SEC, { scale: base }, { easing: "backOut" })
            .start();
    }

    /** 外部注入起始分数（例如主玩法结束时的总分） */
    public setScore(value: number): void {
        this._score = Math.max(0, value);
        this.refreshScoreLabel();
    }

    public get score(): number {
        return Math.floor(this._score);
    }

    private refreshScoreLabel(): void {
        this.totalLabel.string = formatThousands(Math.floor(this._score));
    }

    protected onClickBtn(): void {
        Sfx.play("click");
        // 渠道桥：跳转对应平台商店
        superHtml.download();
    }
}

/** 111222333 → "111,222,333" */
function formatThousands(n: number): string {
    return n.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",");
}
